def sign_of_sequence(seq):
    """Sign of the permutation represented by `seq`, computed by inversions."""
    sign = 1
    items = list(seq)
    for i in range(len(items)):
        for j in range(i + 1, len(items)):
            if items[i] > items[j]:
                sign *= -1
    return sign


